class Solution {
public:
    double average(vector<int>& salary) {
        int n = salary.size();
        int mn = salary[0], mx = salary[0];
        long long sum = 0;
        for (int s : salary) {
            if (s < mn) mn = s;
            if (s > mx) mx = s;
            sum += s;
        }
        return (double)(sum - mn - mx) / (n - 2);
    }
};
